using System.Threading;
using System.Threading.Tasks;

async Task<string> ReadStateAsync(
    string url, CancellationToken cancel, string operation)
{
    using var response = await client.GetAsync(
        url, System.Net.Http.HttpCompletionOption.ResponseHeadersRead, cancel);
    Log(operation, $"HeadersRead status={(int)response.StatusCode}");
    response.EnsureSuccessStatusCode();

    string body = await response.Content.ReadAsStringAsync(cancel);
    Log(operation, "BodyRead");
    using var json = System.Text.Json.JsonDocument.Parse(body);
    string state = json.RootElement.GetProperty("state").GetString()
        ?? throw new System.Text.Json.JsonException("state must not be null");
    Log(operation, $"JsonParsed state={state}");
    return state; // 呼叫端還需決定是否及如何更新畫面。
}
